--liquibase formatted sql
--
-- Catalogue: workspaces, teams, projects, environments, connections, changelogs, pipelines.
-- Reference: docs/05-modelo-de-dados.md § 2.1
--
-- Conventions (docs/05): snake_case, uuid primary keys (v7, generated by the
-- application so they sort by time), timestamptz always in UTC, soft delete via
-- archived_at.

--changeset lqm:001-workspace
create table workspace (
  id         uuid primary key,
  slug       varchar(64) unique not null,
  name       varchar(120) not null,
  -- D-13: AI analysis is a future feature and starts switched off.
  ai_enabled boolean not null default false,
  created_at timestamptz not null default now()
);
--rollback drop table workspace;

--changeset lqm:002-team
create table team (
  id           uuid primary key,
  workspace_id uuid not null references workspace,
  name         varchar(120) not null,
  unique (workspace_id, name)
);
--rollback drop table team;

--changeset lqm:003-project
create table project (
  id             uuid primary key,
  workspace_id   uuid not null references workspace,
  team_id        uuid references team,
  slug           varchar(64) not null,
  name           varchar(120) not null,
  repo_url       varchar(500),
  default_branch varchar(120) default 'main',
  description    text,
  archived_at    timestamptz,
  unique (workspace_id, slug)
);
--rollback drop table project;

--changeset lqm:004-environment
-- An ordered list, configurable per workspace (D-15: DEV/TST/HML/PRD by default).
create table environment (
  id                uuid primary key,
  workspace_id      uuid not null references workspace,
  code              varchar(16) not null,
  name              varchar(60) not null,
  sort_order        int not null,
  color_token       varchar(20) not null,
  is_production     boolean not null default false,
  requires_approval boolean not null default false,
  unique (workspace_id, code)
);
--rollback drop table environment;

--changeset lqm:005-db-connection
-- RNF-06: jdbc_url NEVER carries a username or password. Only the secret reference.
create table db_connection (
  id                   uuid primary key,
  workspace_id         uuid not null references workspace,
  environment_id       uuid not null references environment,
  slug                 varchar(80) not null,
  display_name         varchar(120) not null,
  engine               varchar(30) not null,
  jdbc_url             varchar(500) not null,
  default_schema       varchar(120),
  -- Normalised host:port/database. Lets us match an operation whose collector
  -- did not send a connection key (docs/06, ingestion rule 1).
  host_fingerprint     varchar(200) not null,
  secret_provider      varchar(20),
  secret_ref           varchar(300),
  secret_rotated_at    timestamptz,
  drift_enabled        boolean not null default false,
  drift_cron           varchar(60) default '0 0 */6 * * *',
  scanner_enabled      boolean not null default true,
  scanner_interval_min int default 15,
  db_version           varchar(120),
  last_test_at         timestamptz,
  last_test_ok         boolean,
  archived_at          timestamptz,
  unique (workspace_id, slug)
);
create index ix_db_connection_fingerprint on db_connection (host_fingerprint);
--rollback drop table db_connection;

--changeset lqm:006-project-connection
create table project_connection (
  project_id       uuid references project,
  db_connection_id uuid references db_connection,
  primary key (project_id, db_connection_id)
);
--rollback drop table project_connection;

--changeset lqm:007-changelog
-- policy_package_id gets its foreign key in 004-politicas.sql, once the
-- policy_package table exists.
create table changelog (
  id                uuid primary key,
  project_id        uuid not null references project,
  name              varchar(120) not null,
  path              varchar(500) not null,
  format            varchar(20) not null,
  policy_package_id uuid,
  -- RF-CAD-03 CA1: a changelog discovered through ingestion arrives unverified.
  verified          boolean not null default true,
  unique (project_id, path)
);
--rollback drop table changelog;

--changeset lqm:008-pipeline
create table pipeline (
  id                 uuid primary key,
  workspace_id       uuid not null references workspace,
  name               varchar(80) not null,
  project_id         uuid references project,
  gitlab_project_id  bigint,
  gitlab_trigger_ref varchar(120)
);
--rollback drop table pipeline;

--changeset lqm:009-pipeline-stage
create table pipeline_stage (
  id                uuid primary key,
  pipeline_id       uuid not null references pipeline,
  sort_order        int not null,
  environment_id    uuid not null references environment,
  db_connection_id  uuid not null references db_connection,
  policy_package_id uuid,
  requires_approval boolean not null default false,
  unique (pipeline_id, sort_order)
);
--rollback drop table pipeline_stage;
